/**
 * Preview thumbnails for scrubbing ("trickplay"), generated by Jellyfin 10.9+.
 *
 * Jellyfin stores them as tile sheets: each JPEG is a grid of TileWidth ×
 * TileHeight thumbnails, one every Interval ms, numbered left to right and top
 * to bottom across the sheets.
 */

/** One resolution as Jellyfin describes it on an item's `Trickplay` field. */
export interface JellyfinTrickplayResolution {
	Width: number;
	Height: number;
	TileWidth: number;
	TileHeight: number;
	ThumbnailCount: number;
	Interval: number;
}

/** `item.Trickplay`: media source id → width → resolution. */
export type JellyfinTrickplayManifest = Record<string, Record<string, JellyfinTrickplayResolution>>;

/** What the player needs to show a thumbnail for any moment. */
export interface TrickplayPreview {
	width: number;
	height: number;
	tileWidth: number;
	tileHeight: number;
	thumbnailCount: number;
	/** Seconds between thumbnails. */
	interval: number;
	/** One URL per tile sheet, in order. */
	tileUrls: string[];
}

export interface TrickplayFrame {
	url: string;
	/** Pixel offset of the thumbnail within its sheet. */
	x: number;
	y: number;
}

/** Thumbnails around this width are big enough to recognise and cheap to load. */
const PREFERRED_WIDTH = 320;

function isUsable(resolution: JellyfinTrickplayResolution | undefined) {
	return (
		resolution != null &&
		resolution.Width > 0 &&
		resolution.Height > 0 &&
		resolution.TileWidth > 0 &&
		resolution.TileHeight > 0 &&
		resolution.ThumbnailCount > 0 &&
		resolution.Interval > 0
	);
}

/**
 * Picks the resolution to use for an item and builds its sheet URLs.
 * `toUrl` turns a Jellyfin path into something the browser can load (the
 * stream proxy on the web, a direct URL with a key in the native app).
 * Returns null when the item has no thumbnails.
 */
export function buildTrickplayPreview(input: {
	manifest: JellyfinTrickplayManifest | null | undefined;
	itemId: string;
	mediaSourceId?: string | null;
	toUrl: (path: string) => string;
}): TrickplayPreview | null {
	const { manifest } = input;
	if (!manifest) return null;

	const sourceId =
		input.mediaSourceId && manifest[input.mediaSourceId]
			? input.mediaSourceId
			: Object.keys(manifest)[0];
	if (!sourceId) return null;

	const resolutions = Object.values(manifest[sourceId] ?? {}).filter(isUsable);
	if (!resolutions.length) return null;

	const chosen = resolutions.sort(
		(a, b) => Math.abs(a.Width - PREFERRED_WIDTH) - Math.abs(b.Width - PREFERRED_WIDTH),
	)[0];

	const perSheet = chosen.TileWidth * chosen.TileHeight;
	const sheetCount = Math.ceil(chosen.ThumbnailCount / perSheet);
	const tileUrls = Array.from({ length: sheetCount }, (_, index) =>
		input.toUrl(
			`/Videos/${input.itemId}/Trickplay/${chosen.Width}/${index}.jpg?MediaSourceId=${encodeURIComponent(sourceId)}`,
		),
	);

	return {
		width: chosen.Width,
		height: chosen.Height,
		tileWidth: chosen.TileWidth,
		tileHeight: chosen.TileHeight,
		thumbnailCount: chosen.ThumbnailCount,
		interval: chosen.Interval / 1000,
		tileUrls,
	};
}

/** The thumbnail showing `time` (movie seconds). */
export function getTrickplayFrame(preview: TrickplayPreview, time: number): TrickplayFrame | null {
	if (!Number.isFinite(time) || !preview.tileUrls.length) return null;

	const index = Math.max(
		0,
		Math.min(preview.thumbnailCount - 1, Math.floor(Math.max(0, time) / preview.interval)),
	);
	const perSheet = preview.tileWidth * preview.tileHeight;
	const sheet = Math.floor(index / perSheet);
	const withinSheet = index % perSheet;
	const url = preview.tileUrls[sheet];
	if (!url) return null;

	return {
		url,
		x: (withinSheet % preview.tileWidth) * preview.width,
		y: Math.floor(withinSheet / preview.tileWidth) * preview.height,
	};
}
